inline std::string join_restart_names(const char* const* names, int count, unsigned mask, bool use_and) {
    const Lang l = current_lang();
    int total = 0;
    for (int i = 0; i < count; ++i)
        if ((mask >> i) & 1u) ++total;
    std::string out;
    int idx = 0;
    for (int i = 0; i < count; ++i) {
        if (!((mask >> i) & 1u)) continue;
        if (idx > 0) out += (use_and && idx == total - 1) ? and_sep(l) : list_sep(l);
        out += tr(names[i]);
        ++idx;
    }
    return out;
}

inline std::string tr_restart_line(const char* const* names, int count, unsigned mask, int more, int named) {
    const Lang l = current_lang();
    static constexpr const char* const kHead[kLangCount] = {
        "Restart needed: ", nullptr, "Redémarrage requis : ", nullptr, "Neustart nötig: ",
        "Riavvio necessario: ", "Reinicio necesario: ", nullptr, "Reinício necessário: ",
        "Herstart vereist: ", "Wymagany restart: ", "Нужен перезапуск: ",
        "再起動が必要: ", "재시작 필요: ", "需要重启: ", "需要重新啟動: ",
    };
    std::string line = pick_lang(kHead, l);
    line += join_restart_names(names, count, mask, !more);
    if (more > 0) {
        if (named) {
            static constexpr const char* const kAndMore[kLangCount] = {
                " and %d more", nullptr, " et %d de plus", nullptr, " und %d weitere",
                " e altri %d", " y %d más", nullptr, " e mais %d",
                " en %d meer", " i %d więcej", " и ещё %d",
                " ほか %d 件", " 외 %d개", " 及另外 %d 项", " 及另外 %d 項",
            };
            line += fmt_buf(pick_lang(kAndMore, l), more);
        } else {
            static constexpr const char* const kOne[kLangCount] = {
                "%d setting", nullptr, "%d réglage", nullptr, "%d Einstellung",
                "%d impostazione", "%d ajuste", nullptr, "%d configuração",
                "%d instelling", "%d ustawienie", "%d настройка",
                "%d 項目", "%d개 설정", "%d 项设置", "%d 項設定",
            };
            static constexpr const char* const kMany[kLangCount] = {
                "%d settings", nullptr, "%d réglages", nullptr, "%d Einstellungen",
                "%d impostazioni", "%d ajustes", nullptr, "%d configurações",
                "%d instellingen", "%d ustawień", "%d настроек",
                "%d 項目", "%d개 설정", "%d 项设置", "%d 項設定",
            };
            line += fmt_buf(more > 1 ? pick_lang(kMany, l) : pick_lang(kOne, l), more);
        }
    }
    return line;
}

