/// Concatenation of localized strings for the active language so ui::prebake can rasterize every needed non-ASCII glyph up front.
inline const char* prebake_utf8() {
    static std::string out;
    static Lang built_for = kLangCount;
    const Lang l = current_lang();
    if (built_for == l) return out.c_str();
    built_for = l;
    out.clear();
    if (l == kEnUS) {
        out = "\xE2\x80\x93"; // U+2013 used in inventory range "%d–%d"
        return out.c_str();
    }
    auto add = [&](const char* s) {
        if (!s) return;
        out += s;
    };
    for (const auto& e : kEntries) add(translate_for(l, e.en));
    add(tr_restart_line(nullptr, 0, 0, 2, 1).c_str());
    add(tr_restart_ask(nullptr, 0, 0).c_str());
    add(tr_fps_sub("game 60"));
    add(tr_fps_low("1% low 60"));
    add(tr_startup_step("STEP 1 OF 2"));
    add(tr_startup_left("1 / 2 shaders"));
    add(tr_startup_left("1 / 2 pipelines"));
    add(tr_startup_right("a few seconds left"));
    add(tr_startup_right("about 10 s left"));
    add(tr_startup_right("about 1 min left"));
    add(tr_items_count(1));
    add(tr_quantity(1));
    add(tr_page_of(1, 2));
    add(tr_inv_range(1, 2, 3));
    add(tr_n_of_m(1, 2));
    add(tr_dyn_for(l, "200 nits"));
    add(tr_dyn_for(l, "Native (DLAA, 1920x1080)"));
    add(tr_dyn_for(l, "1920x1080 (native)"));
    add(tr_dyn_for(l, "1920x1080 (game's)"));
    add(tr_dyn_for(l, "0: Device 0"));
    add(tr_dyn_for(l, "Mic (not connected)"));
    add(tr_dyn_for(l, "RX_VK_FIFO or RX_VK_IMMEDIATE is set: it chooses for this run."));
    add(tr_dyn_for(l, "Num 0"));
    add(tr_dyn_for(l, "Key 0"));
    return out.c_str();
}

